(* [comment removed for export] *)
Lemma aobj_ex_place : forall (s : as_St H) LB LF m m1 A n,
  as_RHEAP H s LB m -> as_RFS H LF m1 -> aobj LB LF A n -> 0 <= n -> ex_place H LF A n.
Proof.
  intros s LB LF m m1 A n RH RF AO N0.
  pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AO) as AP. pose proof (aapp_bounds _ _ AP N0) as (B1 & B2 & B3 & B4 & B5).
  split; [eapply (aobj_fsobj H HH); [exact RH| exact AO]|]. split; [exact (aapp_not_shadowland _ _ AP)| lia].
Qed.

(* [comment removed for export] *)
Lemma stack_ex_place : forall LF m A n shi, as_RFS H LF m -> aceil <= A -> 0 <= n -> A + n <= shi -> shi <= AAPP_HI -> ex_place H LF A n.
Proof.
  intros LF m A n shi RF CE N0 HS TOP. pose proof aceil_facts as (AF1 & _).
  split; [eapply (fsobj_high H HH); [exact RF| exact CE]|]. split; [right; unfold AHI_LO in *; lia| lia].
Qed.

Lemma ex_place_sub : forall LF A n A' n', ex_place H LF A n -> A <= A' -> A' + n' <= A + n -> 0 <= n' -> ex_place H LF A' n'.
Proof.
  intros LF A n A' n' (Q1 & Q2 & Q3) L1 L2 N0. split; [eapply fsobj_sub; [exact Q1| exact L1| exact L2]|]. split; [unfold ALOWSH_LO, AHI_LO in *; lia| lia].
