  as_RHEAP H s LB m -> as_RFS H LF m1 -> pch_pure sp P IN E lo shi c p0 bs -> aobj LB LF P 296 -> aobj LB LF E 24 ->
  Forall (aclient_write_ok H LB) (pch_W lo sp P IN E) /\ Forall (afs_write_ok H LF) (pch_W lo sp P IN E) /\ Forall aconst_ok (pch_W lo sp P IN E).
Proof.
  intros s LB LF m m1 lo sp P IN E shi c p0 bs RH RF PURE AOP AOE.
  destruct PURE as (_ & _ & _ & ((LO & CEIL & _ & _ & _ & _ & _ & _ & SHI) & ILO & IHI & IAL) & _).
  unfold PCH_STACK, AASSIGN_STACK, AINTRIN_STACK in LO.
  destruct (stack_window_ok' H HH s LB m LF lo (bv_unsigned sp) RH CEIL) as (S1 & S2 & S3).
  destruct (stack_window_ok' H HH s LB m LF IN (IN + 8) RH ltac:(lia)) as (I1 & I2 & I3).
  destruct (aobj_write_ok H HH _ _ _ _ _ P 80 RH RF (aobj_sub _ _ _ _ P 80 AOP ltac:(lia) ltac:(lia))) as (P1 & P2 & P3).
  destruct (aobj_write_ok H HH _ _ _ _ _ E 24 RH RF AOE) as (E1 & E2 & E3).
  pose proof (ah_fsb H HH _ _ _ RH) as (F1 & F2 & F3 & F4). pose proof (aapp_bounds _ _ F4 ltac:(unfold AFS_SIZE; lia)) as (FB1 & _).
  pose proof pwin_httpcat as [[C3 _] _].
  assert (C1 : aclient_write_ok H LB (AG_HTTP_CAT, AG_HTTP_CAT + 64))
    by (right; left; unfold aimg_client_w, ATLS_PRIV_LO, ATP, AG_HTTP_CAT; cbn [fst snd]; right; right; right; left; clear; lia).
