    by (left; cbn [fst snd]; unfold AG_HTTP_CAT, ATLS_PRIV_LO, ATP, AIMG_TOP in *; split; left; lia).
  unfold pch_W. split; [| split]; (repeat apply Forall_cons; [ | | | | | apply Forall_nil]); assumption.
Qed.
